# Sets status/checkedBy/checkedOn/note on left-or-right claims by textual replacement (keeps the file's layout).
# usage: python3 -I set_status.py path/to/meta.json
import json, sys
P = sys.argv[1]
HEAD = 'Lane left-or-right W-1605 (fact-checker, 2026-10-17, did not write this claim; base d5235af7): '
REC = ' Record: company/reviews/left-or-right/2026-10-17-fact-check.md; own script company/reviews/left-or-right/fc-2026-10-17/own.py.'
V = {
 'c1': ('verified', 'VERIFIED. Rendered text checked in Demo.tsx (reveal paragraph 1, closing sentence, predict key \'No, never\'). Own, kit-free: Kauffman bracket on the 3_1 PD gives V = -t^-4 + t^-3 + t^-1, on its mirror V = t + t^3 - t^4; different, so no deformation joins them. Opened: PMC5582600 (Fielden, Leigh, Woltering, Molecular Knots, Angew 2017) section 2.4: \'The trefoil knot 3 1 is topologically chiral, as one mirror-image form cannot be continuously deformed into the other ... the topological chirality of a trefoil knot was only proven mathematically in the early 20th century [30]\', ref 30 = M. Dehn, Math. Ann. 1914, 75, 402-413; PMC9948535 (ACS Macro Lett 2023) cites Dehn, Die beiden Kleeblattschlingen, Math. Ann. 1914 for \'cannot be continuously transformed into its mirror image\'; Crossref 10.1007/BF01563732 gives title, vol 75, pp 402-413, issued 1914-09. Dehn\'s own text not opened (Springer host). Non-blocking: the source field still names unopened Wikipedia; builder may swap to PMC5582600 + PMC9948535.'),
 'c2': ('verified', 'VERIFIED. Both reveal branches checked in Demo.tsx. Opened: PMC8199745 (DNA-Topology Simplification by Topoisomerases, 2021): \'An amphichiral knot is, by definition, topologically equivalent to its mirror image ... The lowest-order amphichiral knots are the unknot, 0.1, and the figure-eight knot, 4.1\'; PMC5582600 Fig. 6c: \'The figure-eight knot 4 1 can be transformed into its mirror image ... thereby making it topologically achiral\'. Own: kit 4_1 PD has Jones t^-2 - t^-1 + 1 - t + t^2, equal to its mirror\'s (consistent, not a proof); its sum is 0 on all four rest states, so \'summed to 0 both ways\' holds.'),
 'c3': ('verified', 'VERIFIED. Own sign rule: positive when the over-strand\'s arrow turns counter-clockwise (under 180 degrees) onto the under-strand\'s (PMC2853108 Fig. 2E; PMC6698734 Fig. 1B), applied to the PD by own code: 3_1 front -,-,-; own turn-over (planar reflection, then every crossing switched) -,-,-; mirror (page reflection, or every crossing switched) +,+,+; mirrored then turned +,+,+. Own signs read from the kit\'s drawn lines on each rest state\'s screen geometry agree, and QA r4 read the same glyphs and readouts in Chromium (company/reviews/left-or-right/2026-10-16-qa.md). Readout strings from fmt()/hand(): \'Sum −3\' \'Left-handed\', \'Sum +3\' \'Right-handed\'; seenText gives \'Trefoil: turned over −3 · mirror +3\'.'),
 'c4': ('verified', 'VERIFIED. Own PD signs of the kit 4_1 PD: front -,+,-,+; own turn-over -,+,-,+; mirror +,-,+,-; mirrored then turned +,-,+,-; sums 0, so hand() names no hand. Own screen-geometry signs from the drawn lines agree on all four states; QA r4 read the same glyphs. Picture label string checked against ariaLabel(): \'Figure-eight, front. Marks minus, plus, minus, plus. Sum 0.\''),
 'c5': ('disputed', 'DISPUTED: the rule sentence is reversed. With the sign the sources use (PMC2853108 Fig. 2E: turn the over-strand\'s arrow onto the under-strand\'s, \'If that rotation is clockwise, the crossing is negative and it is positive otherwise\'; PMC5582600: \'Positive crossings describe a right-handed helix\'), at a plus crossing the over-strand passes from LEFT to RIGHT as seen travelling along the under-strand (under heading north, over heading east); equivalently, travelling along the over-strand, the under-strand passes from right to left. Own check: right-handed double helix X = sin t, Z = cos t, Y = ct gives over SW-to-NE, under SE-to-NW, i.e. left to right seen from the under-strand. The lesson\'s numbers follow the sources, not this sentence: own signs make the table 3_1 -,-,- and its Jones -t^-4 + t^-3 + t^-1, the left-handed trefoil (PMC2853108: left-handed trefoil writhe about -3.41). So what the learner sees is right (\'Left-handed\' for the table trefoil, \'plus (right-handed)\', sum below 0 called left-handed all check); the claim\'s convention sentence is wrong as written. Fix for demo-builder (claim text only): \'a crossing mark is plus (right-handed) when the over-strand passes from left to right as seen travelling along the under-strand\'. The same reversed sentence is in src/lab/knots/README.md line 37 (Conventions), outside this lane.'),
 'c6': ('verified', 'VERIFIED. Rendered reveal (\'turning over is a way of moving it, so its hand stayed left\', \'turning one over never swaps them\') and recall key \'A right-handed trefoil\' checked. Opened: PMC5582600 glossary \'Chiral knot: A knot that cannot be continuously deformed into its mirror image\' and section 2.4 (deformation \'without the strand passing through itself\'); PMC8199745 (amphichiral = can be continuously deformed into its own mirror image). Own: turning over is rotation by s*pi about an axis in the page, s from 0 to 1, a continuous family of rigid motions, so it is such a deformation; a reflection reverses the orientation of space and lies in no such family. Own computation: turn-over keeps every sign and the Jones polynomial of 3_1; the mirror changes it. Adams not opened; source field swap to PMC5582600 is non-blocking.'),
 'c7': ('verified', 'VERIFIED. Own check on the kit\'s drawings (kit.json): the back face has the same crossing points as the front with the over and under edges exchanged at every crossing (3_1 and 4_1), so the turned rest state (back face shown x -> 100-x, per card.ts and confirmed on screen by QA r4) is the front drawing\'s half-turn: a left-right reflection with every crossing switched. That diagram has the front\'s Jones (same knot), not the mirror\'s. Own signs read from the drawn lines on screen equal the readout on all four rest states of both knots (3_1 -,-,- / -,-,- / +,+,+ / +,+,+; 4_1 -+-+ / -+-+ / +-+- / +-+-). Aria label string checked against ariaLabel().'),
 'c8': ('verified', 'VERIFIED against Demo.tsx: reduced-motion label \'Turned over\'; \'Turn over\' sets rotateY(180deg) on the card (a turn about the vertical axis, left to right); \'Mirror\' sets scaleX(-1) on the wrapper (a left-right reflection in the page), and own code shows a page reflection flips every sign; chips \'Trefoil\' -> 3_1 and \'Figure-eight\' -> 4_1. Own: kit 3_1 Jones has span 3 and the trefoil polynomial, 4_1 span 4 and the figure-eight polynomial; PMC5582600 names \'the trefoil knot 3 1, the figure-eight knot 4 1\'.'),
}
s = open(P, encoding='utf-8').read()
for k, (st, note) in V.items():
    cid = f'"id": "math.left-or-right.{k}"'
    i = s.index(cid)
    old = '"status": "unverified"'
    j = s.index(old, i)
    assert s.find('"id":', i + 1) == -1 or j < s.find('"id":', i + 1)
    ind = '\n      '
    new = f'"status": "{st}",{ind}"checkedBy": "fact-checker",{ind}"checkedOn": "2026-10-17",{ind}"note": {json.dumps(HEAD + note + REC, ensure_ascii=False)}'
    s = s[:j] + new + s[j + len(old):]
json.loads(s)
open(P, 'w', encoding='utf-8').write(s)
print('ok')
